CREATE OR REPLACE FUNCTION public.pm_week_notes_read(_week date) RETURNS jsonb LANGUAGE sql STABLE SECURITY INVOKER SET search_path=public AS $$
 SELECT coalesce(jsonb_agg(to_jsonb(n)||jsonb_build_object('subject_name',CASE WHEN n.kind='project' THEN (SELECT p.name FROM public.pm_projects p WHERE p.id=n.project_id) WHEN n.kind='opportunity' THEN (SELECT o.name FROM public.crm_opportunities o WHERE o.id=n.opportunity_id) END)),'[]'::jsonb) FROM (SELECT DISTINCT ON(kind,project_id,opportunity_id) * FROM public.pm_week_project_notes WHERE week_start<=_week ORDER BY kind,project_id,opportunity_id,week_start DESC) n $$;
COMMENT ON FUNCTION public.pm_week_notes_read(date) IS 'Latest note per subject up to selected week, including its source date and subject name; RLS excludes private week topics from team readers.';